import json

def solve():
    input_str = "( { < { ( ( { } ) ( ) ) } { } < { } > < > > } { } ( { ( { { } } ) [ ( ) ] } ) ) [ ( [ ]"
    tokens = input_str.split()

    matching = {')': '(', '}': '{', '>': '<', ']': '['}
    closing_matching = {'(': ')', '{': '}', '<': '>', '[': ']'}

    stack = []
    for t in tokens:
        if t in closing_matching:
            stack.append(t)
        elif t in matching:
            assert stack and stack[-1] == matching[t], f"Mismatch: {stack[-1]} vs {t}"
            stack.pop()

    # The remaining open brackets must be closed in reverse order
    remaining_closers = [closing_matching[t] for t in reversed(stack)]
    final_answer = " ".join(remaining_closers)

    result = {
        "final_answer": final_answer,
        "evidence": f"Unclosed stack: {stack}, required closers: {remaining_closers}"
    }
    print(json.dumps(result))

if __name__ == "__main__":
    solve()
