    "K": {"Korean"},
    "F": {"French", "German"},
    "B": {"English", "Korean"},
    "G": {"Korean", "French", "English", "German"},
}


def can_communicate(p1, p2):
    return len(languages[p1].intersection(languages[p2])) > 0


nationalities = ["K", "F", "B", "G"]
valid_orders = []

for perm in itertools.permutations(nationalities):
    # perm is a tuple representing rooms 1, 2, 3, 4 (0-indexed: 0, 1, 2, 3)
    pos = {p: i for i, p in enumerate(perm)}

    # 1. Korean: room number larger than German: pos['K'] > pos['G']
    if not (pos["K"] > pos["G"]):
        continue

    # Neighbors of a person at index i
    def get_neighbors(p):
        idx = pos[p]
        neighbors = []
        if idx > 0:
            neighbors.append(perm[idx - 1])
        if idx < 3:
            neighbors.append(perm[idx + 1])
        return neighbors

    # Korean: "nor can I communicate with my neighbors" -> communicates with 0 neighbors
    k_neighbors = get_neighbors("K")
