    # French: "I can't communicate with my neighbors" -> communicates with 0 neighbors
    f_neighbors = get_neighbors("F")
    if any(can_communicate("F", n) for n in f_neighbors):
        continue

    # British: "I can only communicate with one of my neighbors" -> communicates with exactly 1 neighbor
    b_neighbors = get_neighbors("B")
    comm_count_b = sum(can_communicate("B", n) for n in b_neighbors)
    if comm_count_b != 1:
        continue

    valid_orders.append(perm)

mapping = {"G": "Germany", "B": "Britain", "F": "France", "K": "South Korea"}

result_str = [mapping[p] for p in valid_orders[0]]

options = {
    "A": ["Britain", "Germany", "South Korea", "France"],
    "B": ["France", "Britain", "Germany", "South Korea"],
    "C": ["Germany", "Britain", "France", "South Korea"],
    "D": ["Germany", "Britain", "South Korea", "France"],
}

chosen_option = None
for opt, order in options.items():
    if order == result_str:
        chosen_option = opt
        break

output = {
    "final_answer": chosen_option,
    "evidence": f"Unique order: {', '.join(result_str)} matching option {chosen_option}",
}

print(json.dumps(output))
